use super::*;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::*};
#[test]
fn sqlite_snapshot_step_native_preflight_and_bare_binary_text_admission(){
    let snapshot=fixture();assert!(snapshot.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Text,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());let mut finite=fixture();finite.entities[0].args=vec![StepValue::Integer(i64::MIN),StepValue::Real(-0.0),StepValue::Reference(u64::MAX)];let codec=store::ArtifactCodec::bare::<StepSnapshot,crate::standards::v_ap214::subsets::base::schema::mutations::StepMutation>(STDIO_STEP_DOCUMENT_SCHEMA);let provider=codec.snapshot_sqlite.unwrap();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.step".into(),standard:"ap214".into(),subset:"*".into()};for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<StepSnapshot as store::ArtifactPack>::encode_pack(&finite)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<StepSnapshot as store::ArtifactDsl>::print_dsl(&finite))};let database=(provider.export)(&finite.schema,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let restored=(provider.import)(&finite.schema,&dialect,database,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(restored,payload);}assert!(finite.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:1024,..SqliteDatabaseLimits::default()})).is_err());assert!(finite.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());
}
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_step_all_seven_actual_declaration_owned_routes_preserve_words_and_warnings(){
    use semio_framework_os_kernel::io::{ArtifactDialect,io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot}};
    semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("stdio").label("STEP SQLite declaration").version("0.0.1").package_id("semio:stdio").artifact(crate::declaration(crate::definition().unwrap()).unwrap()).try_build().unwrap();
    let snapshot=fixture();let database=project(&snapshot);
    for subset in ["*","cc1","cc2","cc3","cc4","cc5","cc6"]{let dialect=ArtifactDialect{artifact_kind:"s.stdio.step".into(),standard:"ap214".into(),subset:subset.into()};let expected=snapshot.validate_sqlite_snapshot_subset(&dialect,&database,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().diagnostics;for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let mut phases=Vec::new();let exported=io_export_sqlite_snapshot(&dialect,&snapshot,encoding,SqliteDatabaseLimits::default(),&mut |p|{phases.push(p.phase);true}).await.unwrap();assert_eq!(exported.diagnostics,expected);let imported=io_import_sqlite_snapshot::<StepSnapshot>(&dialect,&exported.value,SqliteDatabaseLimits::default(),&mut |p|{phases.push(p.phase);true}).await.unwrap();assert_eq!(imported.diagnostics,expected);assert_eq!(project(&imported.value),database);assert!(!phases.iter().any(|p|matches!(p,SqliteSnapshotPhase::EncodeNative|SqliteSnapshotPhase::DecodeNative)));}}
    let dialect=ArtifactDialect{artifact_kind:"s.stdio.step".into(),standard:"ap214".into(),subset:"cc1".into()};let mut invalid=fixture();invalid.entities[0].name="ADVANCED_BREP_SHAPE_REPRESENTATION".into();assert!(io_export_sqlite_snapshot(&dialect,&invalid,SnapshotEncoding::Binary,SqliteDatabaseLimits::default(),&mut |_|true).await.is_err());let mut invalid=fixture();invalid.header.file_schema.schemas.clear();assert!(io_export_sqlite_snapshot(&dialect,&invalid,SnapshotEncoding::Binary,SqliteDatabaseLimits::default(),&mut |_|true).await.is_err());
}
fn fixture()->StepSnapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let list=|key:&str|f["header"]["fileName"][key].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect();let name=&f["header"]["fileName"];let mut args=vec![StepValue::Unset,StepValue::Derived,StepValue::Integer(i64::MIN),StepValue::Integer(i64::MAX)];for word in f["binary64Words"].as_array().unwrap(){args.push(StepValue::Real(f64::from_bits(u64::from_str_radix(word.as_str().unwrap(),16).unwrap())));}args.extend([StepValue::String("English Deutsch\0文".into()),StepValue::Enum("UNKNOWN".into()),StepValue::Reference(u64::MAX),StepValue::Aggregate(vec![]),StepValue::TypedValue{type_name:"LENGTH_MEASURE".into(),value:Box::new(StepValue::Aggregate(vec![StepValue::Integer(1),StepValue::String(String::new())]))}]);StepSnapshot{schema:f["schema"].as_str().unwrap().into(),header:StepHeader{file_description:StepFileDescription{description:f["header"]["fileDescription"]["description"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),implementation_level:"2;1".into()},file_name:StepFileName{name:name["name"].as_str().unwrap().into(),timestamp:name["timestamp"].as_str().unwrap().into(),author:list("author"),organization:list("organization"),preprocessor_version:name["preprocessorVersion"].as_str().unwrap().into(),originating_system:name["originatingSystem"].as_str().unwrap().into(),authorization:String::new()},file_schema:StepFileSchema{schemas:vec!["AUTOMOTIVE_DESIGN".into(),"AUTOMOTIVE_DESIGN".into()]}},entities:vec![StepEntity{id:1,name:"PRIMARY".into(),args,complex:vec![StepComplexType{name:"COMPLEX".into(),args:vec![StepValue::Reference(1),StepValue::Aggregate(vec![StepValue::Derived,StepValue::Unset])]}]},StepEntity{id:u64::MAX,name:"TARGET".into(),args:vec![StepValue::Reference(1)],complex:vec![]}]}}
fn project(snapshot:&StepSnapshot)->SqliteDatabase{snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(database:&SqliteDatabase)->Result<StepSnapshot,String>{StepSnapshot::from_sqlite_database(database,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]
fn sqlite_snapshot_step_large_scalar_before_copy_controls_and_borrowed_profile_budgets(){
    let mut snapshot=fixture();snapshot.entities[0].args=vec![StepValue::String("文".repeat(40000))];let mut large_checkpoint=false;let mut callback=|progress:SqliteSnapshotProgress|{if progress.phase==SqliteSnapshotPhase::ProjectSnapshot&&progress.completed>=12{large_checkpoint=true;false}else{true}};assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default())).is_err());assert!(large_checkpoint);
    let limits=SqliteDatabaseLimits{max_value_bytes:4096,..SqliteDatabaseLimits::default()};assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());let database=project(&snapshot);assert!(StepSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());
    snapshot.entities[0].name=format!("{}SHAPE_REPRESENTATION","x".repeat(100000));assert!(crate::standards::v_ap214::subsets::cc1::schema::check_cc1_conformance_controlled(&snapshot,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());let mut cancel=false;let mut callback=|p:SqliteSnapshotProgress|{if p.completed>snapshot.header.file_schema.schemas.len(){cancel=true;false}else{true}};assert!(crate::standards::v_ap214::subsets::cc1::schema::check_cc1_conformance_controlled(&snapshot,&mut SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default())).is_err());assert!(cancel);
}
#[test]
fn sqlite_snapshot_step_full_model_all_ieee_words_and_native_state(){let snapshot=fixture();let database=project(&snapshot);let bytes=export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let restored=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(project(&restored),database);assert_eq!(project(&restore(&project(&StepSnapshot::default())).unwrap()),project(&StepSnapshot::default()));let mut finite=fixture();finite.entities[0].args=vec![StepValue::Integer(i64::MIN),StepValue::Real(-0.0),StepValue::Reference(u64::MAX)];let restored=restore(&project(&finite)).unwrap();assert_eq!(<StepSnapshot as store::ArtifactPack>::encode_pack(&restored),<StepSnapshot as store::ArtifactPack>::encode_pack(&finite));assert_eq!(<StepSnapshot as store::ArtifactDsl>::print_dsl(&restored),<StepSnapshot as store::ArtifactDsl>::print_dsl(&finite));}
#[test]
fn sqlite_snapshot_step_rejects_structural_reference_scalar_corruption_and_controls(){let original=project(&fixture());for mutation in 0..5{let mut db=original.clone();match mutation{0=>db.table_mut("step_argument").unwrap().rows[0].values[4]=SqliteValue::Integer(999),1=>db.table_mut("step_value").unwrap().rows.iter_mut().find(|r|r.text(1).unwrap()=="reference").unwrap().values[6]=SqliteValue::Text("00".into()),2=>db.table_mut("step_entity").unwrap().rows[1].values[3]=SqliteValue::Text("1".into()),3=>db.table_mut("step_argument").unwrap().rows[0].values[2]=SqliteValue::Integer(1),_=>db.table_mut("step_description").unwrap().rows[0].values[2]=SqliteValue::Integer(7)}assert!(restore(&db).is_err());}let limits=SqliteDatabaseLimits{max_rows:1,max_value_bytes:1,..SqliteDatabaseLimits::default()};assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(StepSnapshot::from_sqlite_database(&original,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
#[test]
fn sqlite_snapshot_step_independent_sqlite_joins_and_header_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(db.query('SELECT COUNT(*) n FROM step_value GROUP BY kind').all().length!==9||db.query(\"SELECT e.instance_id FROM step_value v JOIN step_entity e ON e.id=v.reference_entity_id WHERE v.reference_instance_id='18446744073709551615'\").get().instance_id!=='18446744073709551615')throw Error('typed graph');db.query(\"UPDATE step_header SET authorization='independent edit'\").run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let restored=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(restored.header.file_name.authorization,"independent edit");}
#[test]
fn sqlite_snapshot_step_exact_typed_profiles_refuse_wrong_coordinates_and_preserve_diagnostics(){let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let mut snapshot=fixture();for entity in &mut snapshot.entities{entity.args.clear();entity.complex.clear();}for(index,name)in f["representationTypes"].as_array().unwrap().iter().enumerate(){snapshot.entities.push(StepEntity{id:100+index as u64,name:name.as_str().unwrap().into(),args:vec![],complex:vec![]});}let database=project(&snapshot);let expected=[crate::standards::v_ap214::subsets::cc1::schema::check_cc1_conformance(&snapshot),crate::standards::v_ap214::subsets::cc2::schema::check_cc2_conformance(&snapshot),crate::standards::v_ap214::subsets::cc3::schema::check_cc3_conformance(&snapshot),crate::standards::v_ap214::subsets::cc4::schema::check_cc4_conformance(&snapshot),crate::standards::v_ap214::subsets::cc5::schema::check_cc5_conformance(&snapshot),crate::standards::v_ap214::subsets::cc6::schema::check_cc6_conformance(&snapshot)];for class in 1..=6{let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.step".into(),standard:"ap214".into(),subset:format!("cc{class}")};let actual=snapshot.validate_sqlite_snapshot_subset(&dialect,&database,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert_eq!(actual.diagnostics,expected[class-1]);}for invalid in f["invalidSqliteDialects"].as_array().unwrap(){let dialect=store::os_io::ArtifactDialect{artifact_kind:invalid["artifactKind"].as_str().unwrap().into(),standard:invalid["standard"].as_str().unwrap().into(),subset:invalid["subset"].as_str().unwrap().into()};assert!(snapshot.validate_sqlite_snapshot_subset(&dialect,&database,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());}}
